// Chargebee on an API key: every operation of Chargebee's API v2 for Product Catalog 2.0 sites (customers,
// subscriptions, invoices, credit notes, items and prices, coupons, quotes, usage, entitlements...), plus the calls only
// Product Catalog 1.0 sites have (plans, addons). actions.json is generated by `bun scripts/openapi-actions.ts chargebee`.
// The person pastes "<site>:<api key>"; calls go to their own <site>.chargebee.com (api.ts). Every event Chargebee
// sends starts automations by webhook (triggers.ts). COVERAGE.md says what's where.
import type { OwnApp } from "../index";
import { call, specActions } from "../openapi";
import { api, parseKey } from "./api";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const FILE = new URL("./actions.json", import.meta.url);
type Spec = { name: string; json?: string[]; send: { query: string[] } };
const specs = new Map(((await Bun.file(FILE).json()) as { actions: Spec[] }).actions.map((a) => [a.name, a]));

// Chargebee's filters are deepObject (created_at[after]=…, status[in]=["a","b"]) and its JSON fields (meta_data) a JSON
// string; the agent gives both as objects, and they're turned into what Chargebee reads here
export function shape(spec: Spec, input: Record<string, unknown>) {
  const out: Record<string, unknown> = { ...input };
  for (const [k, v] of Object.entries(input)) {
    if (!v || typeof v !== "object" || Array.isArray(v)) continue;
    if (spec.json?.includes(k)) out[k] = JSON.stringify(v);
    else if (spec.send.query.some((q) => q.startsWith(`${k}[`))) {
      delete out[k];
      for (const [op, x] of Object.entries(v)) out[`${k}[${op}]`] = Array.isArray(x) ? JSON.stringify(x) : x;
    }
  }
  return out;
}

const actions = await specActions(FILE, api);
for (const [name, a] of Object.entries(actions)) {
  const spec = specs.get(name)!;
  const run = a.run;
  a.run = (i, key, connection) => run(shape(spec, i), key, connection);
}
specs.clear();

const CHECK = { method: "GET", path: "/customers", query: ["limit"], headers: [] };

export const chargebee: OwnApp = {
  app: "chargebee",
  name: "Chargebee",
  logo: "/logos/chargebee.svg",
  keyField: {
    label: "Site and API key",
    help: "Paste your Chargebee site and an API key joined by a colon, like acme:live_a1b2c3. The site is the first part of the address you open Chargebee at (acme for acme.chargebee.com; a test site is acme-test). To make the key, open Settings → Configure Chargebee → API keys and webhooks → API keys, click Add API key, choose Full-access key, name it Emplio and copy it. A read-only key works too, but then Emplio can only look things up and can't react to events.",
    placeholder: "acme:live_a1b2c3d4e5f6...",
  },
  async check(key) {
    const { host } = parseKey(key);
    await call(api, key, CHECK, { limit: 1 });
    return host.replace(/\.chargebee\.com$/, "");
  },
  push: {
    events,
    triggers,
    start: (key, connection) => watch(api, key, connection),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions,
};
